<?php declare(strict_types=1); ?>
<nav class="breadcrumbs" aria-label="<?=$en?'Breadcrumbs':'Đường dẫn'?>"><?php foreach($browse['breadcrumbs'] as $crumb):?><a href="<?=$e($crumb['path'])?>"><?=$e($crumb['name'])?></a><span>/</span><?php endforeach;?><span><?=$e($browse['title'])?></span></nav>
<header class="content-page-heading"><p class="eyebrow"><?=$en?'EXPLORE LOCAL EXPERIENCES':'KHÁM PHÁ TRẢI NGHIỆM'?></p><h1><?=$e($browse['title'])?></h1><?php if($browse['description']!==''):?><p><?=$e($browse['description'])?></p><?php endif;?></header>
<?php if($cover):?><img class="content-page-cover" src="<?=$e($cover)?>" alt="<?=$e($browse['title'])?>"><?php endif;?>
<?php if($browse['children']):?><section class="page-index"><h2><?=$en?'Explore destinations':'Khám phá điểm đến'?></h2><div class="page-grid"><?php foreach($browse['children'] as $child):?><a class="page-card" href="<?=$e($child['localePaths'][$lang])?>"><?php if($media($child['cover'] ?? null)):?><img class="product-thumb" src="<?=$e($media($child['cover']))?>" alt="<?=$e($child['name'])?>" loading="lazy"><?php endif;?><h3><?=$e($child['name'])?></h3><p><?=$e(mb_substr($child['description'],0,180))?></p><span><?=$en?'Explore':'Khám phá'?> ↗</span></a><?php endforeach;?></div></section><?php elseif($browse['kind']==='destinations'):?><p><?=$en?'Destinations are being updated.':'Các điểm đến đang được cập nhật.'?></p><?php endif;?>
<?php if($browse['kind']!=='destinations'):?>
<section class="page-index"><h2><?=$en?'Tickets & local experiences':'Vé & trải nghiệm tại đây'?></h2><form class="catalog-filters" method="get" action="<?=$e($canonicalPath)?>"><label><?=$en?'Find experiences':'Tìm trải nghiệm'?><input type="search" name="q" maxlength="200" value="<?=$e($browse['filters']['q'])?>" placeholder="<?=$en?'Name or destination':'Tên hoặc điểm đến'?>"></label>
<?php if($browse['kind']!=='type'):?><label><?=$en?'Experience type':'Loại trải nghiệm'?><select name="type"><option value=""><?=$en?'All types':'Mọi loại'?></option><?php foreach($browse['types'] as $type):?><option value="<?=$e($type['id'])?>"<?=$browse['filters']['type']===$type['id']?' selected':''?>><?=$e($type['name'])?></option><?php endforeach;?></select></label><?php endif;?>
<?php if($browse['kind']!=='destination'):?><label><?=$en?'Destination':'Điểm đến'?><select name="destination"><option value=""><?=$en?'All destinations':'Mọi điểm đến'?></option><?php foreach($browse['destinations'] as $destination):?><option value="<?=$e($destination['id'])?>"<?=$browse['filters']['destination']===$destination['id']?' selected':''?>><?=$e($destination['name'])?></option><?php endforeach;?></select></label><?php endif;?>
<button class="button" type="submit"><?=$en?'Search':'Tìm kiếm'?></button><a href="<?=$e($canonicalPath)?>"><?=$en?'Reset filters':'Xóa bộ lọc'?></a></form><p role="status"><?=$browse['total']?> <?=$en?'experiences':'trải nghiệm'?></p>
<?php if($browse['products']):?><div class="page-grid"><?php foreach($browse['products'] as $item):?><a class="page-card" href="<?=$e(($en?'/en':'').'/ve/'.$item['slug'])?>"><?php if($media($item['cover'] ?? null)):?><img class="product-thumb" src="<?=$e($media($item['cover']))?>" alt="<?=$e($item['cover']['alt'] ?: $item['name'])?>" loading="lazy"><?php endif;?><p class="eyebrow"><?=$e($item['destination'])?></p><h3><?=$e($item['name'])?></h3><p><?=$e(mb_substr($item['description'],0,180))?></p><span><?=$en?'View experience':'Xem trải nghiệm'?> ↗</span></a><?php endforeach;?></div><?php else:?><p><?=$en?'No matching experiences. Try different filters.':'Chưa có trải nghiệm phù hợp. Thử đổi bộ lọc.'?></p><?php endif;?>
<?php if($browse['pages']>1):$pageHref=static function(int $number)use($browse,$canonicalPath):string{$query=array_filter($browse['filters'],fn($v)=>$v!=='');unset($query[$browse['kind']==='type'?'type':'destination']);$query['page']=$number;return $canonicalPath.'?'.http_build_query($query);};?><nav class="catalog-pagination" aria-label="<?=$en?'Result pages':'Trang kết quả'?>"><?php if($browse['page']>1):?><a href="<?=$e($pageHref($browse['page']-1))?>">← <?=$en?'Previous':'Trước'?></a><?php endif;?><span><?=$en?'Page':'Trang'?> <?=$browse['page']?> / <?=$browse['pages']?></span><?php if($browse['page']<$browse['pages']):?><a href="<?=$e($pageHref($browse['page']+1))?>"><?=$en?'Next':'Sau'?> →</a><?php endif;?></nav><?php endif;?></section>
<?php endif;?>
